INSERT INTO `exercicio` (`ID`, `Nome`, `IdAutor`, `DataCadastro`, `Ativo`, `UsaDescricaoPDF`, `DescricaoHtml`, `Descricao`) VALUES
	(1, 'Teste', 1, '2014-02-01 09:34:33', 1, 1, '                            \n                                \n                                \n                                    Teste de descrição do exercício utilizando o editor HTML, porém não estou colocando nenhum estilo. Quero ver como será exibido o conteúdo deste exercício na listagem dos<span style="color:rgb(255,0,0);"> <b style="color: rgb(255, 0, 0);"><span style="color: rgb(255, 0, 0); font-size: 14px;"><span style="color: rgb(255, 0, 0); font-size: 14px;"><font color="#ff0000" style="color: rgb(255, 0, 0);"><a href="http://www.gay.com.br" style="color: rgb(255, 0, 0);"><span style="color: rgb(255, 0, 0); font-size: 14px;"><span style="font-size: 28px; color: rgb(255, 0, 0);">alunos</span></span></a></font></span></span></b>.</span>\n                                \n                            \n                        ', _binary ),
	(2, 'Maçãs', 1, '2014-02-01 10:19:22', 1, 0, 'Teste de exercício com descrição escrita em <b>html</b>', NULL),
	(3, 'Array de Pontos 2D', 1, '2014-02-09 19:23:07', 1, 0, 'Escreva para a classe <b>ArrayDePontos2D</b> acima um método <i>obtemPontoSuperior</i> que retorne o ponto cuja coordenada y é a maior dentre as encapsuladas no array; um método <i>obtemPontoInferior</i> que retorne o ponto cuja coordenada y é a menor dentre as encapsuladas no array; um método <i>obtemPontoMaisÀEsquerda</i> que retorne o ponto cuja coordenada y é a menor dentre as encapsuladas no array; e um método <i>obtemPontoMaisÀDireita</i> que retorne o ponto cuja coordenada y é a maior dentre as encapsuladas no array.', NULL),
	(4, 'Promoção', 1, '2014-02-27 10:29:01', 1, 0, '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Crie uma classe chamada Produto com os atributos Nome e Preco. Implemente os métodos Gets e Sets.', NULL),
	(5, 'Exercicio 123', 1, '2014-03-08 14:16:00', 1, 0, '                            \r\n                                \r\n                                    Informe a descrição do exercício\r\n                                \r\n                                \r\n                            \r\n                        ', NULL),
	(6, 'Novo Exercício AAA', 1, '2014-03-16 22:16:54', 1, 0, '                            \r\n                                \r\n                                \r\n                                                                                                                                    Preencha aqui o conteúdo do novo exercício!\r\n                                \r\n                            \r\n                        ', NULL),
	(16, 'A Little Bitte Test', 12, '2015-02-05 01:03:09', 1, 0, 'cdsdasdad', NULL);
