	(15, 1, 9, 'Aluno', 'import java.io.PrintWriter;\r\n\r\npublic class Aluno {\r\n\r\n	private String nome;\r\n	private String matricula;\r\n	private String hololo;\r\n\r\n	public String getNome() {\r\n		return this.nome;\r\n	}\r\n\r\n	public void setNome(String nome) {\r\n		this.nome = nome;\r\n	}\r\n\r\n	public String getMatricula() {\r\n		return this.matricula;\r\n	}\r\n\r\n	public void setMatricula(String matricula) {\r\n		this.matricula = matricula;\r\n	}\r\n\r\n	public void imprimeNota() {\r\n		if (this.matricula == "1176511") {\r\n			System.out.print(10);\r\n		} else {\r\n			System.out.print(7);\r\n		}\r\n	}\r\n}\r\n', 'import java.io.PrintWriter;\r\n\r\npublic class Aluno {\r\n\r\n	private String nome;\r\n	private String matricula;\r\n	private String hololo;\r\n\r\n	public String getNome() {\r\n		return this.nome;\r\n	}\r\n\r\n	public void setNome(String nome) {\r\n		this.nosme = nome;\r\n	}\r\n\r\n	public String getMatricula() {\r\n		return "1212121";//this.matricula;\r\n	}\r\n\r\n	public void setMatricula(String matricula) {\r\n		this.matricula = matricula;\r\n	}\r\n\r\n	public void imprimeNota() {\r\n		if (this.matricula == "1176511") {\r\n			System.out.print(10);\r\n		} else {\r\n			System.out.print(7);\r\n		}\r\n	}\r\n}\r\n', '2015-02-04 01:18:54', 1);
